export const ALL_ZONES = "All zones";
export enum MONSTER_ZONES {
  KEEPERS = "Keepers",
  AVIARIA = "Aviaria",
  BUBBLE_COVE = "Bubble Cove",
  OLD_BARK_TOWN = "Old Bark Town",
  KITTY_CITY = "Kitty City",
  ELDER_DRIFTS = "Elder Drifts",
  THE_BRIGHTS = "The Brights",
  ROYAL_GROVES = "Royal Groves",
  ELAND_ISLANDS = "Eland Islands",
  SERPENTINE_HILLS = "Serpentine Hills",
  THE_GLITCH = "The Glitch",
}

export const zoneToSlug = (zone: string): string => {
  return zone.toLowerCase().replace(/ /g, "_");
};

export type ArtTeamMemberCredit =
  | "Benji Nguyen"
  | "Jamie Lai"
  | "Jeff Yin"
  | "Joanna Chan"
  | "Joanna Gerr"
  | "Kelsey Black"
  | "Lily"
  | "Melissa Yuan"
  | "Rachel Fang"
  | "Shuxin Zhan"
  | "Tim Wong";

type MonarchCredit = {
  design?: ArtTeamMemberCredit[];
  render?: ArtTeamMemberCredit[];
  art?: ArtTeamMemberCredit[];
};

export type MonsterDetails = {
  // Puzzmon details
  zone: MONSTER_ZONES;
  name: string;
  displayNameSplit?: string[];
  subtitle?: string;
  imageSrc: string;
  altText: string;
  silhouetteSrc?: string;
  imageSubtext?: string;
  description?: string;
  // The description to show after the overworld is completed.
  friendlyDescription?: string;
  pronunciationSrc?: string;
  credits?: MonarchCredit;
  // Zone-specific fields.
  appetite?: number;
  puzzificationLine?: string[];
  fetchableItems?: FetchableItem[];
  imageSrc2?: string;
  favoriteQuote?: string;
  curiosities?: string[];
  glitchSections?: GlitchSection[];
  dimension?:
    | {
        name: string;
        url: string;
        intro?: string;
        outro?: string;
      }
    | undefined;
  // Monarch task specific fields.
  position?: { x: number; y: number };
  snapshotSrc?: string;
  bubbleCoveTypingTask?: {
    width: number; // width as percentage of background
    behavior: "straight" | "rotated_straight" | "arc" | "pop_out" | "spiral";
    rotation?: number; // degrees of rotation (for rotated_straight behavior)
  };
  order?: number;
  elandIslandsMonarchTask?: {
    // All as percentages of the background.
    top: number;
    width: number;
    left: number;
  };
  serpentineHillsMonarchTask?: {
    specialPowers: (
      | "eat_bombs"
      | "pass_through_walls"
      | "pass_through_itself"
      | "move_rocks"
      | "use_portals"
      | "ice_movement"
      | "only_one_apple"
    )[];
    color:
      | "blue"
      | "brown"
      | "green"
      | "grey"
      | "light_blue"
      | "orange"
      | "dark_orange";
  };
};

export type FetchableItem = {
  src: string;
  alt: string;
  position?: { x: number; y: number };
};

export type GlitchSection = {
  title: string;
  content: string;
};

export type MonsterDetailsMapping = Record<
  MONSTER_ZONES,
  Record<string, MonsterDetails>
>;

export type ZoneTotals = Record<MONSTER_ZONES, number>;

export type MonarchData = Record<
  MONSTER_ZONES,
  {
    solvedPuzzmon: MonsterDetails[];
    count: number;
    taskPrompt?: string;
  }
>;

export type MonarchUnlockUpdate = {
  id: number;
  zone: MONSTER_ZONES;
  puzzmon: MonsterDetails;
  zoneCount: number;
};
